// D — classificação e compatibilidade (0–100) com perfil configurável.
const envelope=$input.first().json||{},jobs=Array.isArray(envelope.jobs)?envelope.jobs:[];
const p=envelope.profile||{};
const norm=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const list=(value,fallback)=>Array.isArray(value)&&value.length?value:fallback;
const stack=list(p.technologies,['Python','Java','C#','.NET','SQL','PostgreSQL','MySQL','Git','Linux','Docker','FastAPI','Unity','JavaScript']);
const role=list(p.roleKeywords,['backend','back-end','full stack','fullstack','desenvolvedor','developer','estagio','programador','qa','game dev','unity']);
const locations=list(p.locations,['Santa Rosa','Rio Grande do Sul','RS']);
const priorities=list(p.priorityAreas,['Backend','Full Stack','QA','Desenvolvimento de Jogos','Unity','Game Dev','IoT']);
const education=list(p.educationKeywords,['sistemas de informacao','ciencia da computacao','analise e desenvolvimento de sistemas','tecnologia da informacao','jogos digitais']);
const practical=list(p.practicalKeywords,['projetos','portfolio','api','integracao','github','desenvolvimento de jogos','unity','iot']);
const weights={technology:30,education:15,practical:20,experience:15,location:15,area:5};
function score(job){
 const title=norm(job.cargo||job.title),body=norm([job.descricao,job.requisitos,job.tecnologias?.join(' '),job.areas?.join(' ')].join(' '));
 const mode=norm(job.modalidade||job.work_mode);
 const location=norm(job.local||job.location);
 const level=norm(job.nivel||job.job_level);
 const hit=terms=>terms.filter(t=>body.includes(norm(t))).length;
 const components={
  technology:Math.round(weights.technology*Math.min(1,hit(stack)/Math.min(Math.max(1,stack.length),5))),
  education:education.some(t=>body.includes(norm(t)))?weights.education:0,
  practical:Math.min(weights.practical,hit(practical)*4),
  experience:/(estag|junior|trainee|entry.level)/.test(level)?15:level==='nao informada'?7:0,
  location:/remot/.test(mode)||locations.some(t=>location.includes(norm(t)))?15:/hibrid/.test(mode)?4:0,
  area:priorities.some(t=>(title+' '+norm(job.area||'')).includes(norm(t)))?5:0
 };
 let points=Object.values(components).reduce((a,b)=>a+b,0);
 const mandatory=norm(job.experiencia||job.experience_requirement)==='obrigatoria'||job.experienciaClassificacao==='EXPERIENCIA_OBRIGATORIA';
 if(mandatory)points-=20;
 points=Math.max(0,Math.min(100,points));
 const label=points>=85?'Excelente':points>=70?'Alta':points>=50?'Intermediária':points>=30?'Baixa':'Pouco compatível';
 return {score:points,notes:'Compatibilidade estimada ('+label+'): tecnologias '+components.technology+'/30; formação '+components.education+'/15; prática '+components.practical+'/20; experiência '+components.experience+'/15; local '+components.location+'/15; área '+components.area+'/5'+(mandatory?'; penalização por experiência obrigatória (-20)':'')+'.'};
}
return [{json:{...envelope,jobs:jobs.map(job=>{
 const result=score(job);
 return {...job,compatibility_score:result.score,compatibility_notes:result.notes};
}),classifiedAt:new Date().toISOString()}}];
